"""Append-only evaluation review targets, with source-change/repair distinctions."""
import copy,datetime,hashlib,importlib.util,json
from pathlib import Path
P=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('replacement_registered_binding',P/'registered_declaration_binding_v2.py');binding=importlib.util.module_from_spec(spec);spec.loader.exec_module(binding)
protocol=json.loads((P/'registered-slugify-real-protocol-v1.json').read_text());oracle=json.loads((P/'slugify-declaration-oracle-v1.json').read_text());registration=copy.deepcopy(protocol['registration']);registration['contracts']['slugify.slugify']={'selector':'slugify','previous_path':'slugify/slugify.py','current_path':'slugify/slugify.py'}
registered=binding.RegisteredDeclaration(registration);template=protocol['cases'][0]['packet'];rows=[];predictions=[]
