 target=({'en':case['selector']+' has a '+case['parameter']+' parameter.','pt-br':case['selector']+' possui parâmetro '+case['parameter']+'.'}if case['current_parameter_present']else copy.deepcopy(case['documentation']))
 packet=copy.deepcopy(template);packet.update(id='replacement-review-'+case['id'],logical_contract_id='slugify.'+case['selector'],documentation=target)
